import{_ as t,c as o,o as r,ah as a}from"./chunks/framework.PvdZnrZd.js";const g=JSON.parse('{"title":"Upgraded Features","description":"Upgraded Features","frontmatter":{"title":"Upgraded Features","description":"Upgraded Features","author":"Chirag Tyagi"},"headers":[],"relativePath":"zenith/upgraded-features/upgraded-features.md","filePath":"zenith/upgraded-features/upgraded-features.md"}'),n={name:"zenith/upgraded-features/upgraded-features.md"};function l(p,e,s,i,d,c){return r(),o("div",null,[...e[0]||(e[0]=[a(`<p><a href="https://store.webkul.com/Shopify-Multi-Vendor-Marketplace.html" target="_blank" rel="noreferrer">Shopify Multivendor Marketplace</a> App New &amp; Upgraded Features: Yes, we are updating and introducing new features to our best featured Multivendor Marketplace app for Shopify.</p><p><em><strong>Please keep following and tracking this section of ours to know about all the updates in the app.</strong></em></p><p>Let&#39;s have a look at the newly introduced and updated features of the Multivendor Marketplace app for Shopify:</p><h2 id="export-the-order-ids" tabindex="-1">Export the order IDs <a class="header-anchor" href="#export-the-order-ids" aria-label="Permalink to &quot;Export the order IDs&quot;">​</a></h2><p>Now, the admin can easily export the order ID details by clicking on the export details. under the payment section.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/06/try5-1200x550.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/06/try5-1200x550.png" alt="try5"></a></p><h2 id="pending-order" tabindex="-1">Pending order <a class="header-anchor" href="#pending-order" aria-label="Permalink to &quot;Pending order&quot;">​</a></h2><p>Now, we have added a &quot;pending orders&quot; button in the admin panel &gt;&gt; order &gt;&gt; order listing section</p><p>which shows that pending orders list in which seller payment is due and added to the seller&#39;s due earnings as per the configuration set by admin in the admin panel.</p><p>By pending orders list, the admin can easily filter out the due payment of their sellers from the order listing.</p><p>For this, the admin just has to click &quot;pending orders&quot; button in order &gt;&gt; order listing as shown in the below image.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesone.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesone.webp" alt="Orders-Admin"></a></p><p>After the admin clicks on the pending orders button, the admin will see that order list in which seller payment is due and will click on &quot;PAY&quot; button to clear the seller due payment</p><p>as shown in the below image.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturestwo.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturestwo.webp" alt="Pending-Orders-Admin"></a></p><p><strong>Note:-</strong><br> The pending orders button will be shown only when the admin has selected &quot;PAY ORDER WISE&quot; in the &quot;SELLER PAYMENT TYPE&quot; dropdown from configuration &gt;&gt; payment configuration.</p><h2 id="order-prepare-status" tabindex="-1">Order Prepare Status <a class="header-anchor" href="#order-prepare-status" aria-label="Permalink to &quot;Order Prepare Status&quot;">​</a></h2><p>The <strong>Order Prepare Status</strong> feature has been updated to reflect changes when an order is <strong>delivered, canceled, or refunded</strong>.</p><p>This ensures accurate order tracking and better transparency for both <strong>admins and sellers</strong> in their respective <strong>order listing pages</strong> within their dashboards.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesthree.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesthree.webp" alt="Order-prepare-status"></a></p><h2 id="add-cc-recipients-to-order-mails" tabindex="-1">Add CC Recipients To Order Mails <a class="header-anchor" href="#add-cc-recipients-to-order-mails" aria-label="Permalink to &quot;Add CC Recipients To Order Mails&quot;">​</a></h2><p>You can now allow sellers to add CC recipients to the emails sent to the customers once an order is placed. For this, visit the admin panel&gt;&gt;Configuration&gt;&gt;Order Configuration&gt;&gt;Enable the tab.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesfour.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesfour.webp" alt="Screenshot-by-Lightshot"></a></p><p>Now, the seller can add up to 5 CC recipients to the order placed email.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesfive.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesfive.webp" alt="Screenshot-by-Lightshot-1"></a></p><h2 id="manage-tip-on-orders" tabindex="-1">Manage Tip on Orders <a class="header-anchor" href="#manage-tip-on-orders" aria-label="Permalink to &quot;Manage Tip on Orders&quot;">​</a></h2><p>Shopify has included an option for customers to add a tip at checkout. <strong><a href="https://help.shopify.com/en/manual/checkout-settings/tips" target="_blank" rel="noreferrer">KNOW MORE</a></strong> Now, you can manage the tip earning in the app.</p><p>Visit the <strong>Seller Payment Configuration</strong> menu of the app and configure if you want to add the tip to the admin&#39;s earnings or the seller&#39;s earnings.</p><p>For this kindly navigate to Multivendor Marketplace Admin Panel &gt;&gt; Go to Payment &gt;&gt; Seller Payment Configuration &gt;&gt;Payment Setting &gt;&gt; &quot;Manage Tip Earning&quot;.</p><p>Refer to the screenshots below:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturessix.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturessix.webp" alt="admin"></a></p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesseven.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesseven.webp" alt="payment"></a></p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeatureseight.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeatureseight.webp" alt="manage tip earning"></a></p><p>As per the configuration, the tip amount entered by the customer will be added to the admin/seller&#39;s earnings in equal proportion.</p><p><strong>For Example</strong>:- Suppose an order of $100 is placed having $80 products of Seller A and $20 products of Seller B.</p><p>A customer entered a tip of $10 at the time of order then, the $8 Tip will be added to the Seller A earning i.e. $88 [$80+$8(Tip)] goes to seller A and</p><p>the $2 will be added to the Seller B earning i.e. $22 [$20+$2(Tip)] goes to seller B.</p><p>In case of refund, you can return the tip to the customer from Shopify and update the same in the app.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/02/download-17-1200x515.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/02/download-17-1200x515.png" alt="download-17"></a></p><h2 id="fraud-analysis" tabindex="-1">Fraud Analysis <a class="header-anchor" href="#fraud-analysis" aria-label="Permalink to &quot;Fraud Analysis&quot;">​</a></h2><p>You can now investigate an order that you think might be fraudulent.</p><p>To check this, you need to visit the Multi-vendor backend&gt;&gt;Go to Orders&gt;&gt;<strong>Order detail page</strong> and view the analysis.</p><p>Both admin and sellers can view the order analysis from their respective panels.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/02/download-18-1200x526.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/02/download-18-1200x526.png" alt="download-18"></a></p><p><strong><a href="https://help.shopify.com/en/manual/payments/fraud-prevention" target="_blank" rel="noreferrer">Know about Fraud Prevention</a></strong></p><h2 id="check-the-mail-log" tabindex="-1">Check the Mail Log <a class="header-anchor" href="#check-the-mail-log" aria-label="Permalink to &quot;Check the Mail Log&quot;">​</a></h2><p>You can now check the mail log info in the app. To do so, please visit the Multi-vendor admin panel&gt;&gt;Mail Configuration&gt;&gt;<strong>Mail Log</strong>.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesnine.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesnine.webp" alt="Home-Admin-2"></a></p><p>Now, select the date range to get the mail log information in the app.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesten.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesten.webp" alt="Mail-Log-Admin"></a></p><p>Please Note:- All the log info will be expired &amp; get removed from the app after 30 days.</p><p>You can view any log info up to 30 days after that it will get deleted automatically. -Date &amp; Time are in UTC format.</p><p>Also Note:- In case you are using other email service provider, you need to contact them to get the information regarding delivered emails.</p><h2 id="sync-inventory-image" tabindex="-1">Sync Inventory &amp; Image <a class="header-anchor" href="#sync-inventory-image" aria-label="Permalink to &quot;Sync Inventory &amp; Image&quot;">​</a></h2><p>In the Multi-vendor Marketplace app, merchant/seller can now <strong>manually sync</strong> the Shopify <strong>product inventory &amp; images</strong></p><p>with that of the marketplace from the <strong>Edit product</strong> section of their respective panels.</p><p>Please Note:- To sync the product inventory and images, the products must be in approval state in the app.</p><p><strong>ADMIN END</strong></p><p>Go to the admin panel&gt;&gt;<strong>Products</strong>&gt;&gt;Product Listing&gt;&gt;<strong>Edit</strong> product&gt;&gt;Sync Inventory &amp; Sync Image (<strong>More Actions</strong>).</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeatureseleven.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeatureseleven.webp" alt="Edit-Product-Admin-2"></a></p><p>Click the <strong>Proceed</strong> button and replace the Shopify inventory with the Multi-vendor app inventory.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturestwelve.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturestwelve.webp" alt="Screenshot-2020-10-26T154051.322"></a></p><p>Similarly, you can replace the Shopify product image with that of the marketplace.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesthirteen.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesthirteen.webp" alt="Screenshot-2020-10-26T163900.975"></a></p><p><strong>SELLER END</strong></p><p>Similarly, the sellers can manually sync the admin&#39;s Shopify product inventory &amp; image with the marketplace inventory &amp; product images.</p><p>Go to the Seller Panel&gt;&gt;Products&gt;&gt;Product Listing&gt;&gt;Edit Product.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesfourteen.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesfourteen.webp" alt="Edit-Product-Seller-•-Multivendor-MarketPlace-1-1"></a></p><h2 id="add-cc-recipients-to-the-email" tabindex="-1">Add CC Recipients To the Email <a class="header-anchor" href="#add-cc-recipients-to-the-email" aria-label="Permalink to &quot;Add CC Recipients To the Email&quot;">​</a></h2><p>In the app, the sellers, customers are notified via email of each action. Now, you have the option to enable the CC tab in the Mail Configuration menu to add CC recipients to the emails.</p><p>Thus, send email notifications to recipients as well.</p><p>To enable this feature, please visit the Multi-vendor Admin Panel&gt;&gt;Go to <strong>Mail Configuration</strong>&gt;&gt;Click the <strong>Edit</strong> button.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesfifteen.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesfifteen.webp" alt="Mail-Configuration-Admin"></a></p><p>As soon as you click the Edit button, you will get the option to <strong>Enable CC</strong> Tab.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturessixteen.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturessixteen.webp" alt="Mail-Configuration-Admin-1"></a></p><p>After enabling this tab, you will get the option to enter the CC recipients in the field given. <strong>Please Note:- You can add a maximum of 5 and a minimum of 1 CC recipient to a mail.</strong></p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesseventeen.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesseventeen.webp" alt="Mail-Configuration-Admin-2"></a></p><p>To add more than one recipient as CC, you just need to add one email ID &amp; clicks the <strong>Enter</strong> and so on.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeatureseighteen.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeatureseighteen.webp" alt="Mail-Configuration-Admin-3"></a></p><p>This way, you can add recipients to the emails.</p><h2 id="seller-store-address-in-mail" tabindex="-1">Seller Store Address in Mail <a class="header-anchor" href="#seller-store-address-in-mail" aria-label="Permalink to &quot;Seller Store Address in Mail&quot;">​</a></h2><p>We are excited to introduce a new enhancement to the <strong>&quot;Customer Items Fulfillment&quot;</strong> email in the <strong>Shopify Multivendor Marketplace</strong> app.</p><p>With this update, admins can now include detailed <strong>seller store information</strong> in the fulfillment emails sent to customers.</p><p>This new feature improves transparency and provides customers with essential seller details, making their post-purchase experience more informative.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesnineteen.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesnineteen.webp" alt="seller-store-address-in-mail"></a></p><p>The following seller-specific variables can now be added to the email template:</p><p><strong>{$seller_store_address}</strong> – Seller’s Store Address</p><p><strong>{$seller_country_name}</strong> – Seller’s Country</p><p><strong>{$seller_state_name}</strong> – Seller’s State</p><p><strong>{$seller_zipcode}</strong> – Seller’s Zip Code</p><h2 id="contact-seller-button-on-product-page" tabindex="-1">Contact Seller Button on Product Page <a class="header-anchor" href="#contact-seller-button-on-product-page" aria-label="Permalink to &quot;Contact Seller Button on Product Page&quot;">​</a></h2><p>You can now display the &quot;Contact Seller&quot; button on the product page of your store.</p><p>Thus, the customers can directly contact the seller of the product they are willing to purchase.</p><p>To do that, you just need to visit the Multi-vendor admin panel&gt;&gt;Configuration&gt;&gt;Instruction for Marketplace&gt;&gt;Get the code.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturestwenty.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturestwenty.webp" alt="Instructions-Admin-1-1"></a></p><p>After adding the codes, you can view the contact button on the product description page of your store.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/09/Customized-Coffee-Mug-%E2%80%93-lalit-store1-1200x597.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/09/Customized-Coffee-Mug-%E2%80%93-lalit-store1-1200x597.png" alt="Customized-Coffee-Mug-–-lalit-store1"></a></p><p>Clicking the <strong>Contact</strong> button, a form appears to which the customer needs to enter the details such as Name, Email ID, and Query.</p><p>Now, filling the details, the customer needs to click the <strong>Submit</strong> button. Thus, submit the query to the respective seller of that product.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/09/Customized-Coffee-Mug-%E2%80%93-lalit-store1-2-1200x597.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/09/Customized-Coffee-Mug-%E2%80%93-lalit-store1-2-1200x597.png" alt="Customized-Coffee-Mug-–-lalit-store1-2"></a></p><p>This way, the customers can send their queries to the sellers of the product.</p><h2 id="display-extra-information-about-the-product-on-your-storefront" tabindex="-1">DISPLAY EXTRA INFORMATION ABOUT THE PRODUCT ON YOUR STOREFRONT <a class="header-anchor" href="#display-extra-information-about-the-product-on-your-storefront" aria-label="Permalink to &quot;DISPLAY EXTRA INFORMATION ABOUT THE PRODUCT ON YOUR STOREFRONT&quot;">​</a></h2><p>This is a newly introduced feature, in which pasting the below code in the product.liquid file</p><p>It will enable you to display extra information about the product on your store&#39;s product description.<br> Therefore, to paste the below given, follow the below process:</p><div class="language-liquid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">liquid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">div</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;wk_product_custom_detail clearfix&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> data-productid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;{{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">product</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">id</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}}&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> style</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;display:none; border-bottom:1px solid #ddd; border-top:1px solid #ddd; padding:5px;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">div</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><ul><li>Go To Themes</li><li>Click on Customize Theme button</li><li>Click on Edit HTML/CSS button</li><li>Select product.liquid file from the Templates where you want to show the link</li><li>Paste the code</li><li>Click on save</li></ul><p><em>Moreover, Pasting this code will enable you to display the custom field you have created for the product description page on the store front end.</em></p><h2 id="display-brand-name-on-product-page-storefront" tabindex="-1">Display Brand Name on product page storefront <a class="header-anchor" href="#display-brand-name-on-product-page-storefront" aria-label="Permalink to &quot;Display Brand Name on product page storefront&quot;">​</a></h2><h4 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h4><p>We have added Brand Name field under product form customisation.</p><p>This field will be disabled by default. Admin needs to enable it fro products &gt;&gt; <strong>product form customization &gt;&gt; brand name</strong></p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturestwentyone.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturestwentyone.webp" alt="brand-name-mvm"></a></p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturestwentytwo.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturestwentytwo.webp" alt="brand-name-configuration"></a></p><p>Once enabled admin can decide if he/she wants to provide this feature globally for all sellers or for some seller only.</p><p>If admin want to enable this feature for some seller then he can enable it from edit seller page</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturestwentythree.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturestwentythree.webp" alt="brand-name-seller-end"></a></p><p>If admin wants this field as global then we have added one brand name configuration under product configuration.</p><p>Navigate from admin panel <strong>configuration &gt;&gt; product configuration &gt;&gt; DISPLAY BRAND NAME</strong></p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturestwentyfour.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturestwentyfour.webp" alt="screenshot_1686659586711"></a></p><p><strong>Note: Once this feature is enabled then brand name field will be available for all seller on product page.</strong></p><h4 id="normal-product-case" tabindex="-1"><strong>Normal Product Case</strong> <a class="header-anchor" href="#normal-product-case" aria-label="Permalink to &quot;**Normal Product Case**&quot;">​</a></h4><p>On product form page Brand Name field will be visible.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturestwentyfive.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturestwentyfive.webp" alt="screenshot_1686659789033"></a></p><p>As a admin you can show this brand name field on product page,</p><p>we have added the code in <strong>instruction for marketplace page which needs to be added in order to show this field on front-end ( customer end )</strong></p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturestwentysix.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturestwentysix.webp" alt="screenshot_1686659733715"></a></p><h4 id="connector-product-case" tabindex="-1"><strong>Connector Product Case</strong> <a class="header-anchor" href="#connector-product-case" aria-label="Permalink to &quot;**Connector Product Case**&quot;">​</a></h4><p>For connector seller as well this field will be visible on product page.</p><p>We have added another page <strong>connector field mapping where seller can map the brand field with their existing field</strong></p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturestwentyseven.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturestwentyseven.webp" alt="brand-name"></a></p><p><strong>For shopify connector seller brand name field should be mapped with &quot;vendor&quot; field</strong>.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2023/06/mapping-1200x518.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2023/06/mapping-1200x518.png" alt="mapping"></a></p><p><strong>In your case products are already imported so once you enable this feature let us know we will sync the products once again for that seller so that brand name field is filled</strong>.</p><p><strong>we have added the code in <strong>instruction for marketplace page which needs to be added in order to show this field on front-end ( customer end )</strong></strong></p><h2 id="custom-field-for-products" tabindex="-1">CUSTOM FIELD FOR PRODUCTS <a class="header-anchor" href="#custom-field-for-products" aria-label="Permalink to &quot;CUSTOM FIELD FOR PRODUCTS&quot;">​</a></h2><p>Earlier we had custom field option only for seller sign up page, now we have introduced the option of a custom field for the product description page on the front end as well.</p><p>The admin will just choose the field whether it is for seller or product from the down while creating a custom field ..and rest everything is the same.</p><p>Go to Custom Field &gt;&gt;&gt; Click on Add custom Field &gt;&gt;&gt; select from dropdown - Seller or product &gt;&gt;&gt; fill in rest of the form &gt;&gt;&gt; click on save.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturestwentyeight.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturestwentyeight.webp" alt="Marketplace15"></a></p><h2 id="reminder-feature" tabindex="-1">REMINDER FEATURE <a class="header-anchor" href="#reminder-feature" aria-label="Permalink to &quot;REMINDER FEATURE&quot;">​</a></h2><p>Also, an extremely amazing feature of the Multivendor marketplace is “Reminder Feature” to remind the vendor for order fulfillment.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturestwentynine.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturestwentynine.webp" alt="Marketplace17"></a></p><h2 id="admin-can-enable-disable-the-option-of-sending-emails" tabindex="-1">Admin can enable/disable the option of sending emails <a class="header-anchor" href="#admin-can-enable-disable-the-option-of-sending-emails" aria-label="Permalink to &quot;Admin can enable/disable the option of sending emails&quot;">​</a></h2><p>Now, admin can enable/disable the option of sending emails and can also edit the content of the automated emails sent to the sellers</p><p>and customers from the mail configuration section.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesthirty.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesthirty.webp" alt="Marketplace19"></a></p><h2 id="invoice" tabindex="-1">Invoice <a class="header-anchor" href="#invoice" aria-label="Permalink to &quot;Invoice&quot;">​</a></h2><p>We have now introduced the feature of generating an invoice on our Multivendor Marketplace App.</p><p>Now in the order section, you can generate the invoice by clicking on the view button of any particular order and then clicking on the generate invoice button.</p><p>The invoice can be generated in two ways :</p><ul><li>Admin to Seller</li><li>Seller to Customer</li></ul><p>And both these types of content can be edited by visiting the invoice configuration section.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesthirtyone.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesthirtyone.webp" alt="Marketplace122"></a></p><p><strong>INVOICE SETTINGS</strong></p><p>From this section the details which will be default will get filled up by admin from this section,</p><p>for example, address, VAT number, VAT, FAX, Telephone Number and much more.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesthirtytwo.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesthirtytwo.webp" alt="Marketplace133"></a></p><blockquote><p><strong><em>Note:</em></strong> <em>From the Admin panel of  Multivendor Marketplace App invoice for Seller from Admin will get generated and from the Seller panel the invoice for Customer/buyer</em></p><p><em>from Seller will get generated when clicked on Generate an Invoice from the order section.</em></p></blockquote><h2 id="order-note" tabindex="-1">Order Note <a class="header-anchor" href="#order-note" aria-label="Permalink to &quot;Order Note&quot;">​</a></h2><p>Now, Customers while placing the order can put the order note for sellers</p><p>which will be visible to the sellers when they will click on the view button of any particular order.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2016/02/Your-Shopping-Cart-%E2%80%93-Multivendor-Marketplace-1.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2016/02/Your-Shopping-Cart-%E2%80%93-Multivendor-Marketplace-1.png" alt="your-shopping-cart-multivendor-marketplace-1"></a></p><h2 id="label-translations" tabindex="-1">LABEL TRANSLATIONS <a class="header-anchor" href="#label-translations" aria-label="Permalink to &quot;LABEL TRANSLATIONS&quot;">​</a></h2><p>Multivendor Marketplace Label Translations feature is here. Now you can rename the labels as per your requirement for various sections of the app.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesthirtythree.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesthirtythree.webp" alt="Marketplace199"></a></p><p>To know more <strong><a href="https://webkul.com/blog/shopify-multivendor-marketplace-label-translations-new-theme/" target="_blank" rel="noreferrer">click here</a></strong>.</p><h2 id="download-invoices-in-bulk" tabindex="-1">Download Invoices in bulk <a class="header-anchor" href="#download-invoices-in-bulk" aria-label="Permalink to &quot;Download Invoices in bulk&quot;">​</a></h2><p>Now you can download the invoices in Bulk. Just go to orders &gt;&gt;&gt; select the orders you want the invoices for &gt;&gt;&gt; from bulk action choose &#39;Bulk Invoice&#39; &gt;&gt;&gt; Save.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesthirtyfour.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesthirtyfour.webp" alt="Marketplace156"></a></p><h2 id="mail-template-header-footer-background-color" tabindex="-1">Mail Template Header &amp; Footer Background Color <a class="header-anchor" href="#mail-template-header-footer-background-color" aria-label="Permalink to &quot;Mail Template Header &amp; Footer Background Color&quot;">​</a></h2><p>Now, the <a href="/zenith/introduction/">multivendor app</a> is upgraded with a new mail template feature within the app. Through this, admin can now change the color of the header&#39;s and footer&#39;s background of the mail template.</p><p><strong>Note</strong>:- This feature is applicable for all mail templates within the app.</p><p>Admin can test this change in header&#39;s and footer&#39;s background color through a &quot;Test Mail&quot; also.</p><p>Follow the procedure to change the header&#39;s and footer&#39;s background color of the mail template:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesthirtyfive.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesthirtyfive.webp" alt="mvm150"></a></p><p>Admin panel of the app &gt;&gt; visit &quot;Mail Configuration&quot; menu &gt;&gt; click it and visit the **&quot;**Mail Template Header and Footer Background Color&quot; section &gt;&gt;</p><p>select the header and footer background color &gt;&gt; click on save button.</p><h2 id="commission-listing-seller-side" tabindex="-1">Commission Listing: Seller Side <a class="header-anchor" href="#commission-listing-seller-side" aria-label="Permalink to &quot;Commission Listing: Seller Side&quot;">​</a></h2><p>Moreover, the sellers can view the list of all the Commissions charged per product from each order.</p><p>For this, go to Shopify Multivendor Marketplace Seller Panel &gt; Orders &gt; Commission Listing:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesthirtysix.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesthirtysix.webp" alt="Commissions Seller • Multivendor MarketPlace"></a></p><h2 id="attach-invoice-seller-to-customer-to-the-order-fulfillment-mail" tabindex="-1">Attach Invoice (Seller To Customer) To The Order Fulfillment Mail <a class="header-anchor" href="#attach-invoice-seller-to-customer-to-the-order-fulfillment-mail" aria-label="Permalink to &quot;Attach Invoice (Seller To Customer) To The Order Fulfillment Mail&quot;">​</a></h2><p>Now, you can choose if you want to send the <strong>order invoice (seller to customer) in the mail</strong> at the time of order to fulfill or not.</p><p>For this, Go to the Mail Configuration&gt;&gt;Select the placeholder &quot;Customer Item Fulfillment&quot;&gt;&gt;Click the &quot;<strong>Edit</strong>&quot; button to edit the mail template.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesthirtyseven-1.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesthirtyseven-1.webp" alt="Mail"></a></p><p>Clicking the edit button, the option to attach invoice enabled!</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesthirtyeight.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesthirtyeight.webp" alt="mail "></a></p><p>This way, you can attach &quot;Seller to Customer&quot; Invoice with the Order fulfillment mail to send it to customers.</p><h2 id="multivendor-marketplace-digital-storage-plans" tabindex="-1">Multivendor Marketplace: Digital Storage Plans <a class="header-anchor" href="#multivendor-marketplace-digital-storage-plans" aria-label="Permalink to &quot;Multivendor Marketplace: Digital Storage Plans&quot;">​</a></h2><p>Wish to increase your Multivendor Marketplace digital storage?</p><p>Check out: <a href="https://webkul.com/blog/multi-vendor-marketplace-for-shopify-digital-storage/" target="_blank" rel="noreferrer">Multi-Vendor Marketplace for Shopify: Digital Storage</a></p><h2 id="add-header-footer-to-the-mail-templates" tabindex="-1">Add Header &amp; Footer to the Mail Templates <a class="header-anchor" href="#add-header-footer-to-the-mail-templates" aria-label="Permalink to &quot;Add Header &amp; Footer to the Mail Templates&quot;">​</a></h2><p>You will now have the option to choose if you want to add header &amp; footer to the mail templates of the mail send to sellers and the customers or not.</p><p>You can visit the <strong>Mail Configuration</strong> menu of the app and enable/disable the settings as per the requirement.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesthirtynine.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesthirtynine.webp" alt="Mail-Configuration admin"></a></p><p>In the mail configuration, scroll down to the bottom and configure the settings.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesfourty.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesfourty.webp" alt="Mail-Configuration-Admin status"></a></p><h2 id="allow-seller-to-cancel-order-fulfillment" tabindex="-1">Allow Seller to Cancel Order Fulfillment <a class="header-anchor" href="#allow-seller-to-cancel-order-fulfillment" aria-label="Permalink to &quot;Allow Seller to Cancel Order Fulfillment&quot;">​</a></h2><p>You can now allow sellers to cancel the order fulfillment from their respective seller panels.</p><p>For this, you need to enable the configuration from the <strong>Order Configuration</strong> menu.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesfourtyone.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesfourtyone.webp" alt="Dashboard-Admin-1"></a></p><p><strong>Enable</strong> the settings &quot;Allow Seller to Cancel Order Fulfillment&quot;:-</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesfourtytwo.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesfourtytwo.webp" alt="Configuration-Admin-2-1"></a></p><p>Now, the sellers will get the option to cancel the fulfillment in their Order detail section.</p><p>Go to Order Listing&gt;&gt;Select a fulfilled order to cancel its fulfillment&gt;&gt;Click the <strong>View</strong> button(Action) menu.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesfourtythree.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesfourtythree.webp" alt="Order-Seller-•-Multivendor-MarketPlace"></a></p><p>On the Order Detail page, the seller will get the option to cancel fulfillment.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesfourtyfour.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesfourtyfour.webp" alt="Order-Details-Seller-•-Multivendor-MarketPlace-3"></a></p><p>Clicking the &quot;Cancel Fulfillment&quot; button, the seller can cancel the fulfillment of an order and the same would reflect in the order detail section of the admin panel.</p><blockquote><p><strong>Note</strong>:- The sellers will not get the option to cancel the order fulfillment in case the order is fulfilled by the admin.</p><p>This feature will work in these shipping methods: FedEx, Vamaship, USPS, UPS, Marketplace Shipping, Free shipping, and Others.</p></blockquote><h2 id="allow-seller-to-accept-reject-order" tabindex="-1">Allow Seller to Accept/Reject Order <a class="header-anchor" href="#allow-seller-to-accept-reject-order" aria-label="Permalink to &quot;Allow Seller to Accept/Reject Order&quot;">​</a></h2><p>You can now choose whether you want the sellers to accept or reject the orders from their respective seller panels.</p><p>Go to Configuration&gt;&gt;Order Configuration&gt;&gt;Enable <strong>Allow Seller to Accept Order</strong>&gt;&gt;Save Changes.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesfourtyfive.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesfourtyfive.webp" alt="accept1"></a></p><p>After enabling this option, the seller will have the option to accept/reject the customer&#39;s order.</p><p>Once an order is placed, the seller needs to visit the <strong>Order Detail</strong> section &amp; perform the action.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesfourtysix.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesfourtysix.webp" alt="Order-Seller-•-Multivendor-MarketPlace"></a></p><p>Clicking the View button, the seller will have the order details, get scroll down to the bottom &amp; in the Fulfillment Detail section, he/she can <strong>Accept</strong> or <strong>Reject</strong> the order.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesfourtyseven.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesfourtyseven.webp" alt="accept or reject"></a></p><p><strong>CASE 1: ACCEPT ORDER</strong></p><p>Clicking the Accept Order button, the seller can accept all the orders at a time and proceed to fulfill the order.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesfourtyeight.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesfourtyeight.webp" alt="accept order"></a></p><p><strong>Order Accepted</strong></p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesfourtynine.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesfourtynine.webp" alt="order accepted"></a></p><p><strong>CASE 2: REJECT ORDER</strong></p><p>Clicking the Reject Order button, the seller needs to give a reason for order rejection &amp; hit the Reject Order button.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesfifty.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesfifty.webp" alt="reject order"></a></p><p><strong>Order Rejected</strong></p><p>This way, the seller rejects the order.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesfiftyone.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesfiftyone.webp" alt="order rejected"></a></p><p>Both admin &amp; the seller can view the order rejection details from their respective panels.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesfiftyone.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesfiftyone.webp" alt="download-19"></a></p><p>For the rejected orders, you can configure an option to cancel the order at the same time. Go to Configuration&gt;&gt;Order Configuration&gt;&gt;AUTO CANCEL ORDER ON REJECT.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesfiftytwo.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesfiftytwo.webp" alt="Screenshot-2020-02-05T162929.842"></a></p><p>In case you <strong>enable</strong> the Auto Cancel Order on Reject option:-</p><p>Then, all the items of this rejected order will get <strong>restocked</strong> and if the order is Paid &amp; Captured, then, the order amount will be refunded.</p><p>In case you <strong>disable</strong> the Auto Cancel Order on Reject option:-</p><p>Then, you need to manually restock the items in your store and manage the refund accordingly.</p><h2 id="allow-seller-to-reject-accepted-orders-before-fulfillment" tabindex="-1"><strong>Allow seller to reject &quot;Accepted&quot; orders before fulfillment</strong> <a class="header-anchor" href="#allow-seller-to-reject-accepted-orders-before-fulfillment" aria-label="Permalink to &quot;**Allow seller to reject &quot;Accepted&quot; orders before fulfillment**&quot;">​</a></h2><p>You can now allow the sellers to reject the orders before fulfillment from their respective seller panels.</p><p>Go to admin Panel&gt;&gt; Configuration&gt;&gt;Order Configuration&gt;&gt;Allow Seller to Accept Order&gt;&gt;Enable Allow Seller to Cancel the Accepted Order&gt;&gt;Save Changes</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesfiftythree.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesfiftythree.webp" alt="accept"></a></p><p>This configuration only works when ALLOW SELLER TO ACCEPT ORDER is ON</p><p>Enable this option to cancel the order if the seller accepts but doesn&#39;t fulfill it.</p><p>To cancel when the seller rejects the order, turn on &#39;AUTO CANCEL ORDER ON REJECT&#39;; otherwise, the order will be rejected.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesfiftyfour.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesfiftyfour.webp" alt="accept"></a></p><h2 id="managed-delivered-order-status-in-mvm" tabindex="-1">Managed &quot;Delivered&quot; order status in MVM <a class="header-anchor" href="#managed-delivered-order-status-in-mvm" aria-label="Permalink to &quot;Managed &quot;Delivered&quot; order status in MVM&quot;">​</a></h2><p>We’ve introduced a new enhancement in our Multi Vendor Marketplace app – <strong>Delivered</strong> status can now be <strong>managed and updated directly within the MVM app</strong>, similar to how Shopify handles order updates.</p><p>Once an order is marked as <strong>fulfilled</strong>, sellers now get the option to <strong>enter delivery details</strong> <strong>manually</strong>.</p><p>They can mark the item as “Delivered” and mention the <strong>exact delivery date</strong> using the <strong>&quot;Enter Delivery Details&quot;</strong> action.</p><p>This brings better sync between the <strong>Shopify order status</strong> and the <strong>MVM panel</strong>, ensuring transparency and efficiency.</p><h2 id="add-expected-delivery-date" tabindex="-1">Add Expected Delivery Date <a class="header-anchor" href="#add-expected-delivery-date" aria-label="Permalink to &quot;Add Expected Delivery Date&quot;">​</a></h2><p>You can allow sellers to add an expected delivery date for the orders.</p><p>For this, you need to visit the admin panel&gt;&gt;Go to Configurations&gt;&gt;Order Configurations.</p><p>Enable the option from here:-</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesfiftyfive.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesfiftyfive.webp" alt="Screenshot-2020-11-26T141937.226"></a></p><p>Once enabled, the seller will get the option to enter the expected delivery date while accepting the order from the order detail section of the seller panel.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesfiftysix.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesfiftysix.webp" alt="Screenshot-2020-11-26T142401.609"></a></p><p>Once the seller accepts the order, the seller will get notified via email with the order delivery details.</p><p>You can customize the emails as per the requirements from the <strong>Mail Configuration</strong> menu in the admin panel.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/11/Screenshot-2020-11-26T142722.418-1200x543.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/11/Screenshot-2020-11-26T142722.418-1200x543.png" alt="Screenshot-2020-11-26T142722.418"></a></p><p>Note:- The expected delivery date variable is provided for the emails.</p><h2 id="wallet-app-compatible-with-multi-vendor-for-discount-via-wallet-feature" tabindex="-1">Wallet App Compatible with Multi-vendor for Discount via Wallet Feature <a class="header-anchor" href="#wallet-app-compatible-with-multi-vendor-for-discount-via-wallet-feature" aria-label="Permalink to &quot;Wallet App Compatible with Multi-vendor for Discount via Wallet Feature&quot;">​</a></h2><p>You might be using the <a href="https://apps.shopify.com/wallet-management" target="_blank" rel="noreferrer">Wallet Management app</a> to offer a discount to your customers via Webkul wallet.</p><p>Now, if the &quot;<strong>Manage Discount on Orders</strong>&quot; tab is ON from the Seller payment Configuration of the Multi-vendor app then</p><p>the discount offered to customers via Webkul Wallet (through Wallet Management App) will be managed in the app.<br><a href="https://webkul.com/blog/multivendor-marketplace-manage-discount/" target="_blank" rel="noreferrer">Know how to Manage Discount on Orders</a></p><p>The amount paid via wallet will appear in the invoice of each order placed on your store.</p><p>Kindly navigate to Multivendor Marketplace Admin Panel &gt;&gt; Go to Payment &gt;&gt; Seller Payment Configuration &gt;&gt;Payment Setting &gt;&gt; Enable the option “Manage discount on order”.</p><p>Refer to the screenshots below:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesfiftyseven.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesfiftyseven.webp" alt="admin"></a></p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesfiftyeight.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesfiftyeight.webp" alt="payment"></a></p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesfiftynine.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesfiftynine.webp" alt="manage discount on order"></a></p><p>**PLEASE NOTE:-<br> **If you have already downloaded the invoice or if you have saved the previous invoice template</p><p>then the &quot;Pay via Wallet&quot; option will not appear in the order invoice both on seller invoice as well as customer invoice.</p><p>If any of the above is the case, you can either reset the template on your own or <a href="https://webkul.uvdesk.com/en/customer/login" target="_blank" rel="noreferrer"><strong>send a request</strong></a> for the same. We will do it for you.</p><p>This is how the &quot;Pay via Wallet&quot; option will appear in the Order Invoice:</p><p><strong>Merchant to Seller Invoice:-</strong></p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/03/Print-Invoice-Admin-%E2%80%A2-Multivendor-MarketPlace-1200x597.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/03/Print-Invoice-Admin-%E2%80%A2-Multivendor-MarketPlace-1200x597.png" alt="paid via wallet"></a></p><p><strong>Seller to Customer Invoice:-</strong></p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/03/Print-Invoice-Seller-%E2%80%A2-Multivendor-MarketPlace-1200x597.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/03/Print-Invoice-Seller-%E2%80%A2-Multivendor-MarketPlace-1200x597.png" alt="seller to customer invoice"></a></p><h2 id="allow-seller-to-create-order-on-behalf-of-customer" tabindex="-1">Allow Seller to Create Order on Behalf of Customer <a class="header-anchor" href="#allow-seller-to-create-order-on-behalf-of-customer" aria-label="Permalink to &quot;Allow Seller to Create Order on Behalf of Customer&quot;">​</a></h2><p>You can now allow your sellers to create orders on behalf of your customers in case the seller receives orders via call. You just need to enable the configuration in the app.</p><p><strong>NOTE</strong>:- Please make sure that the Account Email (on Shopify End) and Business Email (in the app) is the same to use the Draft Order feature.</p><p>Login to Multi-vendor Admin Panel&gt;&gt;Go to <strong>Configuration</strong>&gt;&gt;<strong>Order Configuration</strong>&gt;&gt;Enable the option &quot;Allow Sellers to create order&quot;&gt;&gt;Save Changes.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturessixty.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturessixty.webp" alt="draft order "></a></p><p>Once enabled, the sellers will get the option to create order from their respective seller panels.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturessixtyone.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturessixtyone.webp" alt="orders"></a></p><p>The seller will click the &quot;Create Draft Order&quot; button and proceed to create an order on customer request.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturessixtytwo.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturessixtytwo.webp" alt="create order"></a></p><p>Clicking the Create Draft Order button, the seller needs to enter all the details such as:-</p><p>Customer email ID, choose whether the customer wants to place a tax-exempt order or not, choose to include products in the order.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturessixtythree.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturessixtythree.webp" alt="draft order"></a></p><p>After entering all the details, the seller will be able to create draft orders for customers.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturessixtyfour.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturessixtyfour.webp" alt="create order"></a></p><p>Soon after creating a draft order, the <strong>customer will receive an email</strong> on the registered email ID <strong>to make the payment</strong>.</p><p>So, the customer will check the complete order details &amp; total amount &amp; <strong>pay for the order</strong>.</p><p>List all the draft orders on a separate section of the seller panel:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturessixtyfive.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturessixtyfive.webp" alt="view order"></a></p><p>Clicking the View button, the seller can view the draft order details:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturessixtysix.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturessixtysix.webp" alt="order details"></a></p><p>This way, you can allow sellers to create orders on behalf of their customers if requested via call, email,etc.</p><h2 id="shopify-order-fulfillment-email" tabindex="-1">Shopify Order Fulfillment Email <a class="header-anchor" href="#shopify-order-fulfillment-email" aria-label="Permalink to &quot;Shopify Order Fulfillment Email&quot;">​</a></h2><p>If you don&#39;t want customers to receive the order fulfillment emails from Shopify end then,</p><p>here is an option in the app. Please visit the <strong>Order Configuration</strong> menu and disable this tab.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturessixtyseven.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturessixtyseven.webp" alt="Configuration_Admin-2"></a></p><h2 id="create-shopify-private-apps-in-mvm" tabindex="-1">Create Shopify Private Apps in MVM <a class="header-anchor" href="#create-shopify-private-apps-in-mvm" aria-label="Permalink to &quot;Create Shopify Private Apps in MVM&quot;">​</a></h2><p>You can now add a maximum of 5 private apps to the Multi-vendor Marketplace app.</p><p>You can create Shopify Private Apps and configure them in the app to resolve the API limit issue.</p><p>NOTE:-<br> From here, you can add <strong>a maximum of 5 private apps</strong> to the multi-vendor app.<br> Firstly, you need to <strong>provide the required permissions</strong> in the Shopify private app.</p><p><strong>PERMISSIONS REQUIRED</strong></p><ol><li>For <strong>PRODUCT:</strong>- View or manage products, variants, and collections<br> Access scopes: read_products, write_products</li><li>For <strong>INVENTORY</strong>:- View or manage inventory across multiple locations<br> Access scopes: read_inventory, write_inventory</li></ol><p>Version Supported:- The webhook API version should be <strong>2020-01</strong></p><p><strong>MARK:- Be very specific about the permissions. If it is wrong, no data will be updated as no API gets hit.</strong></p><p>To Add a Shopify Private App into the app, you need to visit the admin panel&gt;&gt;Configurations&gt;&gt;click <strong>Shopify Private App</strong> sub-menu.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturessixtyeight.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturessixtyeight.webp" alt="Dashboard-Admin-1"></a></p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturessixtynine.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturessixtynine.webp" alt="Shopify-Private-Apps-Admin"></a></p><p>Clicking the Add Shopify Private App button, you need to configure the details such as Private App Name, API key and Secret Key.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesseventy.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesseventy.webp" alt="Add-Shopify-Private-App-Admin"></a></p><p>Get the details from Shopify Manage Private App section.<br><strong>HOW TO CREATE PRIVATE APP ON SHOPIFY</strong> and how to get the Admin API Details.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/07/prince-store1-Edit-Shopify-MVM-1-Shopify-1200x597.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/07/prince-store1-Edit-Shopify-MVM-1-Shopify-1200x597.png" alt="prince-store1-Edit-Shopify-MVM-1-Shopify"></a></p><p>Also Note:- In case you want to delete the private app on Shopify, firstly you need to delete/disable the same in the app.</p><p>Otherwise, the access token will get expired and no API call gets hit from the Multi-vendor app.</p><p><a href="/zenith/configuration/shopify-custom-apps.html">Explore more about shopify custom/private app in details</a></p><h2 id="avalara-avatax" tabindex="-1">Avalara Avatax <a class="header-anchor" href="#avalara-avatax" aria-label="Permalink to &quot;Avalara Avatax&quot;">​</a></h2><p><a href="https://www.avalara.com/us/en/index.html" target="_blank" rel="noreferrer">Avalara</a> is now integrated with the Multi-vendor Marketplace app for Shopify to let merchants automate the sales tax calculation for sellers products too.</p><p>There are a few restrictions to use this feature:-</p><ul><li>The merchant needs to install the Avalara Avatax app in the Shopify admin.</li><li>The Avalara Avatax is available only with the Shopify Plus plan.</li></ul><p>To enable the feature in the app, you need to visit the Product Configuration and enable the option AVALARA AVATAX.</p><p>Now, you will have two options to add &quot;Tax codes&quot; in the app.</p><p>Either to a product that will be applied to all the variants of the respective product OR you can apply product type-wise tax code.</p><p><strong>CASE 1:- Add Tax code based on Product Type.[&quot;Restrict Product Type&quot; Enabled]</strong></p><p><strong>Note</strong>:- To add the product type-wise tax code, it is mandatory to enable “Restrict Product Type” from the Restriction configuration menu.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesseventyone.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesseventyone.webp" alt="Configuration-Admin-3"></a></p><p>After enabling the AVALARA AVATAX, you need to enable the &quot;Product Type wise Tax code&quot; option.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesseventytwo.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesseventytwo.webp" alt="Configuration-Admin-4"></a></p><p>Now, you can enter a separate tax code for each product type and the seller will select the same while adding the product.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesseventythree.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesseventythree.webp" alt="Add-Product-Type-Admin"></a></p><p><strong>CASE 2: Add Tax Code directly to Products [&quot;Restrict Product Type&quot; Disabled]</strong></p><p>In this case, you just need to enable the AVALARA AVATAX option in the Product Configuration menu and proceed to add tax codes.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesseventyfour.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesseventyfour.webp" alt="Configuration-Admin-2"></a></p><p>You need to visit the Product section and click the &quot;Add Product&quot; button. Now, enter the product type and add tax code.</p><p>This tax code will be applied to all the variants of that product. Later, you can change the tax code by editing the variant.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesseventyfive.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesseventyfive.webp" alt="Add-Product-Admin"></a></p><p>This way, you can manage the automatic tax calculation for seller&#39;s products too via Avalara AvaTax.</p><h2 id="export-commission" tabindex="-1"><strong>Export Commission</strong> <a class="header-anchor" href="#export-commission" aria-label="Permalink to &quot;**Export Commission**&quot;">​</a></h2><p>In the Multivendor Marketplace, you can now export commission details by selecting a specific date range.</p><p><strong>For exporting commission, you need to navigate to-<br> Admin dashboard&gt;&gt;Commission&gt;&gt;Commission Listing&gt;&gt;Export Details</strong></p><p>Choose the required fields from the options on the left and specify a date range to retrieve commission data for the selected period.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesseventysix.webpwebp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesseventysix.webpwebp" alt="commission"></a></p><p>Click the <strong>&quot;Export&quot;</strong> button to download the commission data as a .csv file for the chosen date range.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesseventyseven.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesseventyseven.webp" alt="commission2"></a></p><p>Use the <strong>&quot;Save &amp; Export&quot;</strong> option to save the selected fields (added to &quot;Saved Lists&quot;). Then download the commission data as a .csv file for the specified date range.</p><p>The <strong>&quot;Saved List&quot;</strong> feature displays all saved field configurations, allowing quick selection of a date range and easy downloading of the commission data as a .csv file.</p><h2 id="total-sales-column-in-seller-export-csv" tabindex="-1">&quot;Total Sales&quot; Column in Seller Export CSV <a class="header-anchor" href="#total-sales-column-in-seller-export-csv" aria-label="Permalink to &quot;&quot;Total Sales&quot; Column in Seller Export CSV&quot;">​</a></h2><p>Admins can now include a Total Sales column when exporting seller details.</p><p>The total sales of a seller represent the total revenue earned from all goods they have sold within a given period.</p><p>For exporting Seller Details navigate to: <strong>Admin Dashboard&gt;&gt;Seller&gt;&gt;Seller Listing&gt;&gt; Export Details</strong>.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesseventyeight.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesseventyeight.webp" alt="seller
"></a></p><p>Simply check the box for <strong>Total Sales</strong> while selecting the columns, and the information will be included in your exported file.</p><h2 id="option-to-send-digital-download-mail-on-the-order-description-page" tabindex="-1"><strong>Option to send &quot;Digital Download Mail&quot; on the Order Description page</strong> <a class="header-anchor" href="#option-to-send-digital-download-mail-on-the-order-description-page" aria-label="Permalink to &quot;**Option to send &quot;Digital Download Mail&quot; on the Order Description page**&quot;">​</a></h2><p>In the Multivendor Marketplace, admins can send digital download emails directly to customers from the <strong>&#39;Order Details&#39;</strong> section.</p><p><strong>To send Digital Download Mails, Admin needs to navigate to<br> Orders&gt;&gt;Order Listing&gt;&gt; Hover over on 3 dots&gt;&gt; View&gt;&gt;More actions&gt;&gt;Send Digital Download Mail</strong></p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2024/11/order-1-1200x602.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2024/11/order-1-1200x602.webp" alt="order"></a></p><p>This new feature is available exclusively for digital products, ensuring a seamless delivery experience for the admin and the customer.</p><p><strong>Note: This option will appear once the order is paid or fulfilled.</strong></p><p><a href="/zenith/configuration/configuration-updates.html"><strong>CONFIGURATION UPDATES</strong></a></p><p><a href="/zenith/configuration/seller-configuration.html"><strong>SELLER UPDATES</strong></a></p><p><a href="/zenith/configuration/product-configration.html"><strong>PRODUCT UPDATES</strong></a></p><h2 id="filter-orders-by-customer-name-in-order-listings" tabindex="-1">Filter Orders by Customer Name in Order Listings <a class="header-anchor" href="#filter-orders-by-customer-name-in-order-listings" aria-label="Permalink to &quot;Filter Orders by Customer Name in Order Listings&quot;">​</a></h2><p>If the admin wants to view a specific seller&#39;s orders in the order listing, they can apply the &#39;Search by Customer Name&#39; filter.</p><p>Once the filter is applied, only the orders related to the selected seller&#39;s products will be visible.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesseventynine.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/upgradedfeaturesseventynine.webp" alt="Filter"></a></p><h3 id="demo" tabindex="-1">DEMO <a class="header-anchor" href="#demo" aria-label="Permalink to &quot;DEMO&quot;">​</a></h3><p>You can refer the below-given link to check the demo of multivendor marketplace App for Shopify:-</p><p><a href="https://multivendor-marketplace-5.myshopify.com/pages/seller-profile" target="_blank" rel="noreferrer">https://multivendor-marketplace-5.myshopify.com/pages/demo</a></p><p>Keep following this blog of ours to know about all the recent updates.</p>`,376)])])}const h=t(n,[["render",l]]);export{g as __pageData,h as default};
